def test_stop_base_and_other_annotation_is_stop_base():
    import inspect
    from tenacity.stop import stop_base
    hints = {}
    for name, param in inspect.signature(stop_base.__and__).parameters.items():
        if name == 'other':
            annotation = param.annotation
            hints['other'] = annotation
    # The annotation for 'other' should be the string "stop_base", not an empty string ''
    assert hints.get('other') == 'stop_base', (
        f"Expected annotation 'stop_base' for 'other' parameter, got {hints.get('other')!r}"
    )

def test_stop_base_and_return_annotation_is_stop_all():
    import inspect
    import tenacity.stop as stop_module

    hints = {}
    try:
        import typing
        hints = typing.get_type_hints(stop_module.stop_base.__and__)
    except Exception:
        pass

    # If get_type_hints fails or returns empty, fall back to __annotations__
    if not hints:
        annotations = getattr(stop_module.stop_base.__and__, '__annotations__', {})
        return_annotation = annotations.get('return', '')
    else:
        return_annotation = hints.get('return', '')

    # The return annotation should reference stop_all, not be empty string
    annotation_str = str(return_annotation)
    assert 'stop_all' in annotation_str, (
        f"Expected 'stop_all' in return annotation of stop_base.__and__, got: {annotation_str!r}"
    )

