def test_dissoc_boundary_uses_remaining_path():
    from toolz.dicttoolz import dissoc

    class NoDeletionDict(dict):
        def __delitem__(self, key):
            raise RuntimeError("deletion not allowed")

    factory = NoDeletionDict

    # len(keys)=3, len(d)=5, 3 == 5*0.6 exactly
    # Original (<): 3 < 3.0 is False -> uses remaining path (no deletion) -> OK
    # Mutated (<=): 3 <= 3.0 is True  -> uses update+delete path -> RuntimeError
    d = {1: 'a', 2: 'b', 3: 'c', 4: 'd', 5: 'e'}
    result = dissoc(d, 1, 2, 3, factory=factory)
    assert result == {4: 'd', 5: 'e'}

