def test_dissoc_path_threshold_mutation():
    from toolz.dicttoolz import dissoc
    # len(keys)=1, len(d)=1: original 1<0.6 False→path2; mutant 1<1.6 True→path1
    # Both give {}. Need observable difference via factory side effects.
    updates = []
    class TrackingDict(dict):
        def update(self, other):
            updates.append(list(other.keys()))
            super().update(other)
    result = dissoc({'x': 1}, 'x', factory=TrackingDict)
    assert result == {}
    assert 'x' not in result

def test_dissoc_path_selection_boundary():
    from toolz.dicttoolz import dissoc
    # At len(keys)=2, len(d)=3: original: 2<1.8→False(path2); mutant: 2<4.8→True(path1)  
    # At len(keys)=1, len(d)=2: original: 1<1.2→True(path1); mutant: 1<3.2→True(path1) - same
    # Need a case where original→path2, mutant→path1, with different observable output
    # For standard dict, both paths are equivalent. Use factory that tracks behavior.
    deleted = []
    class MyDict(dict):
        def __delitem__(self, key):
            deleted.append(key)
            super().__delitem__(key)
    result = dissoc({'a':1,'b':2,'c':3}, 'a', 'b', factory=MyDict)
    assert result == {'c': 3}

